const CONTEXT_INSTRUCTION =
  '### CONTEXT GUIDANCE\nUse the provided context to inform the tone and style, but do not output the context itself.';

export interface BuiltPrompt {
  systemPrompt: string;
  userPrompt: string;
}

export function buildWriterPrompt(
  inputText: string,
  options: Partial<AIWriterCreateOptions> = {}
): BuiltPrompt {
  const tone = options.tone || 'neutral';
  const format = options.format || 'markdown';
  const length = options.length || 'short';
  const sharedContext = options.sharedContext?.trim() || '';
  const targetLanguageName = getLanguageDisplayName(options.outputLanguage);

  const key = `${tone}|${format}|${length}`;
  let systemPrompt =
    WRITER_PROMPT_LOOKUP[key] || WRITER_PROMPT_LOOKUP['neutral|markdown|short'];

  // Replace hardcoded Japanese language instruction with selected or auto language
  const languageReplacement = targetLanguageName
    ? `**Language:** You MUST write exclusively and entirely in ${targetLanguageName}. DO NOT mix languages or include words/phrases from other languages for any reason.`
    : "**Language:** You MUST write in the same language as the user's INSTRUCTIONS unless explicitly requested otherwise.";

  systemPrompt = systemPrompt.replace(
    /\*\*Language:\*\* You MUST write exclusively and entirely in Japanese\. DO NOT mix languages or include words\/phrases from other languages for any reason\./g,
    languageReplacement
  );

  if (!sharedContext) {
    systemPrompt = systemPrompt.replace(CONTEXT_INSTRUCTION, '').trim();
  }

  let userPrompt = '';
  if (sharedContext) {
    userPrompt = `CONTEXT: ${sharedContext}\n\nINSTRUCTIONS: ${inputText}`;
  } else {
    userPrompt = `INSTRUCTIONS: ${inputText}`;
  }

  return {
    systemPrompt,
    userPrompt,
  };
}
